# -*- coding: utf-8 -*-
"""Pend part A: hanging, suspension and attachments. Imported by final author."""
from lesson_authoring import entry as E
def S(w):return 'https://www.etymonline.com/word/'+w
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
H=[['拉丁 pendēre；相关动词 pendere','悬垂；使悬挂、称量']]
SU=H+[['拉丁 sub- 的同化形式 sus- + pendere → suspendere','从下托起、挂起；也指暂时停止'],['古法语 sospendre／拉丁借入 → 中古英语 suspenden → suspend','暂停、暂时解除职务；也用于悬挂']]
SP=H+[['拉丁 suspendere → 分词 suspensus','挂起、停止 → 悬着、未定'],['盎格鲁法语 suspens／古法语 sospense → 英语 suspense','事情暂不作决定 → 等待结果的紧张感']]
AP=H+[['拉丁 ad- + pendere → appendere','挂到某物上；附上'],['古法语 apendre、拉丁借入 → 英语 append','早期归属、依附义；现代附加义涉及后来的再借入']]
W=[
E('pending','英、美 /ˈpendɪŋ/','待处理的；尚未决定的；等待……期间','事情还挂在半空，没有落下最终结果：申请等批准，订单等处理，决定等更多信息。','与拉丁 pendere“悬挂”和法语 pendant“在……期间”相连。英语 pending 很可能部分仿译法语法律用语，也有与 pendent“未决定的”相关的分析；不能只当成一个常用现代动词 pend 的普通进行时。',[['拉丁“事情悬着”一类表达；法语 pendant','案件、判断未决；法语分词又作“期间”的介词'],['英语 pending','部分仿译或英语化形式，表示待决及等待……期间']],'形容词：The request is pending，申请还未处理完。介词：pending approval，等候批准期间、以获批为条件。pending 并不自动表示出了错误，也不能当成已经 approved。','a pending request；pending approval；remain pending；pending further review。','pending 是等待处理或结果，impending 是即将发生。pending payment 是付款尚未完成；impending payment 强调某次付款快到来。',('Your application is still pending.','你的申请仍在处理中。'),('The opening date is provisional, pending final approval.','开放日期暂定，尚待最终批准。'),sources=[S('pending'),K('pending'),'https://www.merriam-webster.com/dictionary/pending']),
E('impending','英、美 /ɪmˈpendɪŋ/','即将发生的；逼近的','像一件事已经悬在头顶，眼看就要发生。常带压力或不祥感，但也能说快到来的重要时刻。','英语 impend + -ing；impend 借拉丁 impendere，im- 来自 in-“在……上”，pend- 是悬挂。这一 im- 不是“不”的否定前缀。',H+[['拉丁 in- + pendere → impendere','悬在上方 → 迫近、即将发生'],['英语 impend + -ing → impending','迫近的、即将发生的']],'impending disaster 是迫近的灾难；impending departure 是即将离开，不一定是坏事。重点是时间或感觉上已经很近，通常作名词前的定语。','impending disaster；an impending deadline；impending departure；a sense of impending change。','pending 重在未决，impending 重在将发生。imminent 也表示即将发生，与 impending 很接近。',('The dark clouds suggested an impending storm.','乌云预示着暴风雨即将来临。'),('Her impending departure made the final meeting unusually emotional.','她即将离开，让最后一次见面格外动情。'),sources=[S('impend'),K('impending'),O('impending')]),
E('suspend','英、美 /səˈspend/','悬挂；暂停；暂时停职、停学；使悬浮','把东西挂住，它暂时不往下落；把活动“挂起来”，它暂时不往前走。这个画面能连起悬挂与暂停。','sus- 是拉丁 sub- 的同化形式，与 pendere 组成 suspendere。经古法语或直接拉丁借入英语；暂停义在早期英语中已经存在，不是现代才从挂东西临时比喻出来。',SU,'suspend talks 是暂停谈判；suspend a lamp 是把灯吊起。suspend someone from duty 是暂时停止其职务。暂停不保证多久恢复，也不等于一定永久取消。','suspend operations；suspend judgment；suspend someone from duty；suspend a lamp from the ceiling。','cancel 通常取消，suspend 通常暂时中止。hang 很日常，suspend 在悬挂义上更正式，也能用于颗粒悬浮。',('The organisers suspended the match because of heavy rain.','由于大雨，组织者暂停了比赛。'),('The sculpture is suspended from thin steel cables.','这座雕塑由细钢索悬吊着。'),sources=[S('suspend'),K('suspend'),O('suspend')]),
E('suspended','英、美 /səˈspendɪd/','悬挂着的；被暂停的；被暂时停职的；悬浮的','动作已经发生，现在东西仍挂着、活动仍停着，或细小颗粒分散在介质中。','英语 suspend + -ed；末尾 /d/ 后的 -ed 读 /ɪd/。既可作过去式，也可用过去分词描述暂停、悬挂后的状态。',SU+[['英语 suspend + -ed → suspended','被悬挂、被暂停或悬浮的状态']],'a suspended ceiling 是吊顶；suspended particles 是悬浮颗粒。suspended operations 指暂时停下的业务。要根据后面的对象判断，不能把所有 suspended 都译为“停职”。','suspended operations；suspended particles；a suspended ceiling；was suspended from duty。','suspended 与 dissolved 不同：颗粒悬浮不等于已经溶解。stopped 说停了，suspended 常保留暂时中止的含义。',('The suspended lights cast circles on the floor.','悬吊的灯在地板上投下一个个光圈。'),('The service was suspended while the fault was investigated.','调查故障期间，这项服务暂停了。'),sources=[K('suspended'),S('suspend'),O('suspend')]),
E('suspension','英、美 /səˈspenʃən/','暂停；停职、停学；悬挂；悬架；悬浮液','把“挂住或暂停的状态”当作一件事来讲。汽车里是连接车身和车轮、缓和颠簸的悬架；液体里可以是分散着固体颗粒的悬浮液。','接拉丁 suspensio／suspensionem，来自 suspendere 的分词词干 suspens-；也有法语对应形式。现代虽和 suspend 对应，名词已有独立拉丁来源。',H+[['拉丁 suspendere → suspensus → suspensio／suspensionem','挂起、暂停 → 相应状态或动作名词'],['英语 suspension','暂停、悬挂；后发展汽车与液体分散体系等用法']],'the suspension of service 是服务暂停；a car’s suspension 是车的悬架系统。a suspension in water 可指颗粒分散在水中的体系，它与完全溶解形成的溶液不同。','temporary suspension；a suspension of service；car suspension；a suspension bridge。','suspense 是等待结果时的紧张感，suspension 是暂停、悬挂等过程或状态。不要用 suspension 来泛指电影“悬念”。',('The notice announced a temporary suspension of deliveries.','通知宣布暂时停止送货。'),('The car’s suspension absorbed much of the vibration from the rough road.','汽车的悬架缓和了崎岖路面带来的许多震动。'),('The powder formed a cloudy suspension in water.','粉末在水中形成了浑浊的悬浮液。'),sources=[S('suspension'),K('suspension'),O('suspension')]),
E('suspense','英、美 /səˈspens/','悬念；紧张期待；悬而未决的焦虑','结果迟迟不揭晓，心就一直悬着：门后是谁，考试有没有通过，故事中的人能不能逃出去。','经盎格鲁法语 suspens、古法语 sospense，接拉丁 suspensus“悬着、被暂停的”，来自 suspendere。早期有法律上的暂缓、未决义，后来发展出等待结果的心理状态。',SP,'keep someone in suspense 是让人继续悬着心等答案。悬念可以让小说好看，也可以让现实中的等待难熬；它不必总是愉快的期待。','build suspense；keep someone in suspense；a moment of suspense；a suspense novel。','surprise 是突然知道结果的惊讶，suspense 是还不知道时的紧张。好的故事可以先制造 suspense，再给 surprise。',('The director builds suspense by keeping the camera outside the locked room.','导演让镜头一直停在锁住的房门外，以此制造悬念。'),('Don’t keep us in suspense—tell us what happened.','别让我们悬着心了，快说发生了什么。'),sources=[S('suspense'),K('suspense'),O('suspense')]),
E('suspenseful','英、美 /səˈspensfəl/','充满悬念的；令人紧张期待的','让你忍不住继续看，因为事情还没揭晓，下一步又似乎很关键。','英语 suspense + -ful；-ful 在这里表示带有、充满这种效果，不是可以单独搬出一个 full 来作历史借入解释。',SP+[['英语 suspense + -ful → suspenseful','带来悬念、让人紧张期待的']],'a suspenseful scene 不一定有暴力或恐怖画面。一个人等电话、门把手慢慢转动，也能通过节奏和信息控制形成悬念。','a suspenseful scene；a suspenseful ending；a suspenseful thriller。','scary 是吓人的；suspenseful 是让人急于知道结果。比赛结尾可以 suspenseful，却不一定 scary。',('The last chapter is suspenseful without relying on a surprise villain.','最后一章没有靠突然冒出的反派，也写得悬念十足。'),('A long silence makes the scene even more suspenseful.','一段长长的沉默让这个场景更令人紧张期待。'),sources=[K('suspenseful'),O('suspenseful'),S('suspense')]),
E('suspender','英 /səˈspendə/；美 /səˈspendər/','吊带；背带的一根；使物体悬挂的支承物','一根带子把衣物往上拉住，让它不会往下滑。','英语 suspend + -er，表示起悬吊作用的人或物；衣物用法中通常是带子。-er 不是只能指职业人物。',SU+[['英语 suspend + -er → suspender','起悬吊、支承作用的东西；衣物带子']],'英式衣物语境常指吊住长袜的小带；美式常指裤子肩带中的一根。谈一整副裤子背带，通常用复数 suspenders。','a suspender strap；a suspender clip；a suspender belt。','suspender 单数突出其中一根或一个部件；suspenders 复数常作为整副衣物配件的名称。不同地区所指衣物不同。',('One suspender had slipped off his shoulder.','他的一根裤子背带从肩上滑落了。'),('The costume designer replaced a broken suspender clip.','服装设计师换掉了一个坏掉的吊带夹扣。'),sources=[K('suspender'),O('suspender'),S('suspend')]),
E('suspenders','英 /səˈspendəz/；美 /səˈspendərz/','裤子背带〔美式〕；吊袜带〔英式〕','把衣物吊住的一组带子。美式画面通常是从肩上跨过的裤子背带；英式画面通常是吊住长袜的带子。','suspender 的复数，远接 suspend“悬吊”。作为衣物配件名称经常用复数，类似 a pair of trousers 中整件衣物的复数形式。',SU+[['英语 suspender → suspenders','一组用于支承衣物的带子'],['地区用法分化','美式常为裤子背带；英式常为吊袜带']],'a pair of suspenders 在美式里是一副裤子背带；英国人说同样的裤子背带，常用 braces。听到 suspenders 时，地区和服装场景都很重要。','a pair of suspenders；wear suspenders；adjust the suspenders。','braces 在英式衣物语境可对应美式 suspenders；garter、suspender belt 则是吊袜相关的词。不能只背一个中文而忽视地区差别。',('He wore red suspenders with his white shirt.','他穿着白衬衫，配了一副红色裤子背带。'),('The British costume catalogue lists stockings and suspenders together.','这份英国服装目录把长袜和吊袜带列在一起。'),sources=[K('suspenders'),O('suspender')]),
E('pendant','英、美 /ˈpendənt/','吊坠；悬垂饰物；吊灯','最典型的画面是链子下面垂着一件小饰物。重点是它悬在别的东西下面。','来自盎格鲁法语 pendaunt、古法语 pendant，原为 pendre“悬挂”的现在分词，再作名词，远接拉丁 pendere。不是英语 pen 加 dant。',H+[['法语 pendre → 分词 pendant；名词化','悬挂 → 垂挂着的东西'],['英语 pendant','吊坠、悬饰；也指悬吊灯具']],'a silver pendant 是银吊坠，a pendant light 是吊灯。pendant 不一定包含整条项链，也不专指宝石；木头、金属等饰物都可以。','a pendant on a chain；a silver pendant；a pendant light。','necklace 是项链整体；pendant 是垂挂的饰物。pedant 是卖弄学问、拘泥细节的人，拼写相近而词源不同。',('A small pendant hung from a thin chain around her neck.','一枚小吊坠垂在她脖子上的细链子下。'),('Three pendant lights hang above the kitchen counter.','三盏吊灯悬在厨房操作台上方。'),sources=[S('pendant'),K('pendant'),O('pendant')]),
E('pendulum','英、美 /ˈpendʒələm/','摆；钟摆；来回摇摆的趋势','把重物吊在固定点下面，让它左右来回摆。这个动作又能比喻意见、风格或政策在两个方向之间摇摆。','借近代拉丁 pendulum，是拉丁 pendulus“悬垂的”的中性名词化形式，远接 pendere“挂”。近代拉丁名称也可能受意大利语 pendolo 影响。',H+[['拉丁 pendulus → 近代拉丁名词 pendulum','悬垂的 → 可以自由摆动的悬挂物'],['英语 pendulum','物理摆、钟摆；引申为来回变化的趋势']],'a clock pendulum 是钟摆。the pendulum swings back 可说风潮又朝反方向转，但这只是比喻，不保证现实变化必然像钟摆那样规则。','a clock pendulum；the swing of a pendulum；the pendulum swings towards／away from。','pendant 重点是垂挂的物件；pendulum 重点是能围绕支点来回摆动。不是每个吊坠都作为钟摆使用。',('The pendulum moved steadily from side to side.','钟摆稳稳地左右摆动。'),('In fashion, the pendulum often swings between simplicity and extravagance.','时尚潮流常常在简约和奢华之间来回转向。'),sources=[S('pendulum'),K('pendulum'),O('pendulum')]),
E('penchant','英常读 /ˈpɒ̃ʃɒ̃/，也读 /ˈpentʃənt/；美 /ˈpentʃənt/','偏爱；爱好；倾向','心总往某个方向倾斜：别人随意选，你却经常选那一类东西。','借法语 penchant，原是 pencher“倾斜”的分词名词化形式。pencher 一般经重构的通俗拉丁 *pendicare 联系到 pendere“悬挂”；星号表示中间形式为重构，不是已见于文献的确证词。',H+[['重构通俗拉丁 *pendicare → 古法语 pencher','倾斜、偏向'],['法语 penchant → 英语 penchant','倾向某方 → 对某事的偏爱']],'have a penchant for something 是偏爱某物，也可接动名词。它不必强到成为嗜好或成瘾；说爱开玩笑、喜欢旧家具都很自然。','a penchant for old books；a penchant for telling stories；show a penchant for。','preference 强调比较后的偏好；penchant 常突出一贯、自然而然的倾向。与 pendant 吊坠的读音和拼写都要区分。',('She has a penchant for buying notebooks she never fills.','她总爱买笔记本，却从来写不满。'),('His penchant for elaborate jokes sometimes puzzled his colleagues.','他爱讲复杂笑话的习惯，有时让同事们摸不着头脑。'),sources=[S('penchant'),K('penchant'),O('penchant')]),
E('append','英、美 /əˈpend/','附加；追加到末尾','主内容已经在那里，再把一段补充接到它后面，像在文件尾部挂上一小段。','接拉丁 ad-“到……上”+ pendere 构成 appendere。英语早期经古法语借入的是归属、依附义；现代“附上”用法又涉及从拉丁或法语再借入，不必把所有义项画成一条不断线的英语发展。',AP,'append a note to a report 是把说明附在报告后。计算机里 append 常说向已有列表、字符串或文件末尾追加；是否改变原对象取决于具体工具，词义本身只突出接在后面。','append a note to；append data to a file；append an item to a list。','add 很宽，可以加到任何位置；append 通常指末尾附加。prepend 则是加在开头。',('Please append a short explanation to the end of the report.','请在报告末尾附上一段简短说明。'),('The program appends each new entry to the log file.','程序把每条新记录追加到日志文件末尾。'),sources=[S('append'),K('append'),O('append')]),
E('appended','英、美 /əˈpendɪd/','附上的；追加了的','补充内容已经接到了主文后面，读者可以顺着正文继续往后找。','英语 append + -ed。原词以 /d/ 结尾，-ed 读 /ɪd/，所以 appended 的最后一段是 /dɪd/。',AP+[['英语 append + -ed → appended','附加完成；描述已追加的内容']],'the appended table 是附上的表格；a note appended to the email 是附在邮件后的说明。它可以直接接在正文后，不必是一个单独的附件文件。','the appended notes；an appended table；appended to the document。','attached 也说附上，但可以是另一个附件；appended 更明确地让人想到主内容末尾的补充。',('The appended table lists the assumptions used in the calculation.','附表列出了计算所采用的假设。'),('She appended a correction to the original message.','她在原消息后追加了一条更正。'),sources=[K('appended'),S('append'),O('append')]),
E('appendage','英、美 /əˈpendɪdʒ/','附属物；附肢；附在较大整体上的部分','主体旁边伸出或附着的一部分：昆虫的触角、建筑旁的小附楼，都可以从“接在主体上”理解。','英语 append + -age，形成表示所附加部分的名词。虽然常见于生物学，但不是专门只指手脚，也不是从英语 appendix 换词尾而来。',AP+[['英语 append + -age → appendage','附在主体上的部分']],'身体 appendage 可以是附肢等外伸结构。比喻说某人被当成 an appendage，是批评其独立价值被忽视，仿佛只是别人的附带部分。','a bodily appendage；an appendage to the main building；a mere appendage。','appendix 常指书的附录或阑尾；appendage 是较宽的附属部分，二者不能在所有场景互换。',('The insect uses its long appendages to sense movement nearby.','这只昆虫用长长的附肢感知附近的动静。'),('She refused to be treated as a mere appendage to her husband’s career.','她不愿被当成丈夫事业的附属品。'),sources=[S('appendage'),K('appendage'),O('appendage')]),
E('appendix','英、美 /əˈpendɪks/','附录；阑尾','书后附着的一块补充内容，与身体里附在盲肠上的小管状结构，都沿用了“附加在主体上”的名称。','直接借拉丁 appendix“附着物、补充”，来自 appendere“挂上、附上”。英语书面附录义与后来的解剖义有各自记录，不能说是从现代 append 现场加一个 -ix 后缀。',H+[['拉丁 appendere → appendix','附上 → 附加物、补充'],['英语 appendix 的书面义','附在正文后的资料'],['英语解剖义','小的器官附属结构；尤其指阑尾，可能受法语解剖用法影响']],'See Appendix A 是“见附录 A”。在身体语境里 appendix 通常是阑尾，不等于整个盲肠。复数 appendices、appendixes 都可见；书籍中 appendices 很常用。','Appendix A；in the appendix；remove the appendix；appendices to a report。','index 是索引，帮助查找内容；appendix 是补充资料。appendectomy 是阑尾切除术，appendicitis 是阑尾炎。',('The questionnaire is reproduced in the appendix.','问卷全文收录在附录中。'),('The anatomy lesson showed where the appendix is attached to the bowel.','解剖课展示了阑尾附着在肠道的什么位置。'),sources=[S('appendix'),K('appendix'),O('appendix'),'https://www.nhs.uk/conditions/appendicitis/']),
]
